package config;

import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Properties;

/** Application settings: config/app.properties, overridden by JVM system properties. */
public final class Settings {
    private static final Path DEFAULT_FILE = Path.of("config", "app.properties");

    private final Properties values;

    private Settings(Properties values) {
        this.values = values;
    }

    public static Settings load() {
        return load(DEFAULT_FILE);
    }

    public static Settings load(Path file) {
        Properties props = new Properties();
        if (Files.isRegularFile(file)) {
            try (InputStream in = Files.newInputStream(file)) {
                props.load(in);
            } catch (IOException e) {
                throw new IllegalStateException("cannot read " + file, e);
            }
        }
        for (String name : System.getProperties().stringPropertyNames()) {
            if (name.startsWith("password.") || name.startsWith("session.") || name.startsWith("profile.")) {
                props.setProperty(name, System.getProperty(name));
            }
        }
        return new Settings(props);
    }

    public static Settings of(Properties props) {
        Properties copy = new Properties();
        copy.putAll(props);
        return new Settings(copy);
    }

    public String value(String key, String fallback) {
        String v = values.getProperty(key);
        return v == null || v.isBlank() ? fallback : v.trim();
    }

    public int intValue(String key, int fallback) {
        String v = value(key, null);
        if (v == null) {
            return fallback;
        }
        try {
            return Integer.parseInt(v);
        } catch (NumberFormatException e) {
            return fallback;
        }
    }

    public boolean boolValue(String key, boolean fallback) {
        String v = value(key, null);
        return v == null ? fallback : Boolean.parseBoolean(v);
    }
}
=== src/crypto/PasswordHasher.java
package crypto;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.util.Base64;

/** Salted SHA-256, stored as {@code salt$digest} (both base64). */
public final class PasswordHasher {
    private static final int SALT_BYTES = 16;
    private static final int ROUNDS = 1_000;

    private final SecureRandom random = new SecureRandom();

    public String hash(String raw) {
        byte[] salt = new byte[SALT_BYTES];
        random.nextBytes(salt);
        return encode(salt) + "$" + encode(digest(salt, raw));
    }

    public boolean matches(String raw, String stored) {
        if (raw == null || stored == null) {
            return false;
        }
        int sep = stored.indexOf('$');
        if (sep <= 0) {
            return false;
        }
        byte[] salt = Base64.getDecoder().decode(stored.substring(0, sep));
        byte[] expected = Base64.getDecoder().decode(stored.substring(sep + 1));
        return MessageDigest.isEqual(expected, digest(salt, raw));
    }

    private static byte[] digest(byte[] salt, String raw) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] out = raw.getBytes(StandardCharsets.UTF_8);
            for (int i = 0; i < ROUNDS; i++) {
                md.reset();
                md.update(salt);
                md.update(out);
                out = md.digest();
            }
            return out;
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    private static String encode(byte[] bytes) {
        return Base64.getEncoder().withoutPadding().encodeToString(bytes);
    }
}
