import config.Settings;
import crypto.PasswordHasher;
import domain.PasswordPolicy;
import domain.PolicyViolation;
import service.PasswordHistoryGuard;
import store.CredentialHistoryStore;
import util.EmailAddresses;

import java.util.List;
import java.util.Properties;

import static java.util.List.of;

public class UnitChecks {
    public static void main(String[] args) {
        PasswordHasher hasher = new PasswordHasher();
        String h1 = hasher.hash("correct horse 1");
        String h2 = hasher.hash("correct horse 1");
        TestSupport.check(!h1.equals(h2), "hasher: same password hashes differently (salted)");
        TestSupport.check(hasher.matches("correct horse 1", h1) && hasher.matches("correct horse 1", h2), "hasher: both hashes verify");
        TestSupport.check(!hasher.matches("correct horse 2", h1), "hasher: wrong password does not verify");
        TestSupport.check(!hasher.matches("x", "garbage"), "hasher: malformed hash does not verify");

        Properties p = new Properties();
        p.setProperty("a.int", " 7 ");
        p.setProperty("a.bad", "seven");
        p.setProperty("a.flag", "false");
        Settings s = Settings.of(p);
        TestSupport.check(s.intValue("a.int", 1) == 7, "settings: trims ints");
        TestSupport.check(s.intValue("a.bad", 3) == 3, "settings: bad int falls back");
        TestSupport.check(s.intValue("missing", 4) == 4, "settings: missing int falls back");
        TestSupport.check(!s.boolValue("a.flag", true), "settings: booleans");

        TestSupport.check("Bob.Smith@example.com".equals(EmailAddresses.normalize(" Bob.Smith@EXAMPLE.com ")), "email: domain lower-cased, local part kept");
        TestSupport.check(!EmailAddresses.looksValid("no-at-sign"), "email: rejects missing @");

        PasswordPolicy policy = new PasswordPolicy(10, true, 5);
        TestSupport.check(policy.check("erin", "short1").equals(of(PolicyViolation.TOO_SHORT)), "policy: too short");
        TestSupport.check(policy.check("erin", "no digits here").equals(of(PolicyViolation.MISSING_DIGIT)), "policy: digit required");
        TestSupport.check(policy.check("erin", "hello-erin-2024").contains(PolicyViolation.CONTAINS_USERNAME), "policy: username inside password");
        TestSupport.check(policy.check("erin", "a perfectly fine 9").isEmpty(), "policy: good password");

        CredentialHistoryStore store = new CredentialHistoryStore();
        for (int i = 0; i < 30; i++) {
            store.append("u1", "hash-" + i);
        }
        TestSupport.check(store.size("u1") == 24, "history: capped");
        TestSupport.check(store.recent("u1", 3).equals(List.of("hash-29", "hash-28", "hash-27")), "history: newest first");
        TestSupport.check(store.recent("nobody", 3).isEmpty(), "history: unknown account");

        PasswordHistoryGuard guard = new PasswordHistoryGuard(new CredentialHistoryStore(), hasher);
        guard.remember("u2", hasher.hash("first password 1"));
        guard.remember("u2", hasher.hash("second password 2"));
        TestSupport.check(guard.usedRecently("u2", "first password 1", 2), "guard: older password inside window");
        TestSupport.check(!guard.usedRecently("u2", "first password 1", 1), "guard: older password outside window");

        TestSupport.finish("unit");
    }
}
import api.Response;
import app.Application;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;

import static java.util.Map.of;

public class AccountApiTest {
    public static void main(String[] args) {
        Clock clock = Clock.fixed(Instant.parse("2026-04-01T09:00:00Z"), ZoneOffset.UTC);
        Application app = Application.create(clock, "admin-key");

        // sign-up validation
        Response weak = TestSupport.call(app, "POST", "/accounts", null,
                TestSupport.body("username", "frank", "email", "frank@example.com", "password", "short"));
        TestSupport.check(weak.status() == 422, "sign-up with a short password is rejected (got " + weak.status() + ")");
        String token = TestSupport.signUpAndLogin(app, "grace", "first-Pass-001");
        Response dup = TestSupport.call(app, "POST", "/accounts", null,
                TestSupport.body("username", "grace", "email", "other@example.com", "password", "first-Pass-001"));
        TestSupport.check(dup.status() == 409, "duplicate username is rejected (got " + dup.status() + ")");

        // profile
        Response renamed = TestSupport.call(app, "PUT", "/me/profile", token, of("displayName", "  Grace H. "));
        TestSupport.check(renamed.status() == 200 && "Grace H.".equals(TestSupport.field(renamed, "displayName")), "display name can be changed");

        // password change: wrong current password, policy, then success
        Response wrongCurrent = TestSupport.call(app, "PUT", "/me/password", token,
                of("currentPassword", "nope", "newPassword", "second-Pass-002"));
        TestSupport.check(wrongCurrent.status() == 403, "change with wrong current password is refused (got " + wrongCurrent.status() + ")");
        Response noDigit = TestSupport.call(app, "PUT", "/me/password", token,
                of("currentPassword", "first-Pass-001", "newPassword", "no-digits-at-all"));
        TestSupport.check(noDigit.status() == 422, "new password without a digit is refused (got " + noDigit.status() + ")");
        Response changed = TestSupport.call(app, "PUT", "/me/password", token,
                of("currentPassword", "first-Pass-001", "newPassword", "second-Pass-002"));
        TestSupport.check(changed.status() == 200, "password change succeeds (got " + changed.status() + ")");
        Response relogin = TestSupport.call(app, "POST", "/sessions", null, of("username", "grace", "password", "second-Pass-002"));
        TestSupport.check(relogin.status() == 201, "login with the new password works");

        // security policy: recently used passwords cannot be chosen again
        Response back = TestSupport.call(app, "PUT", "/me/password", token,
                of("currentPassword", "second-Pass-002", "newPassword", "first-Pass-001"));
        TestSupport.check(back.status() == 422, "switching back to the previous password is refused (got " + back.status() + " " + back.body() + ")");

        TestSupport.finish("account api");
    }
}
import api.Request;
import api.Response;
import app.Application;

import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class TestSupport {
    static int failed = 0;

    private TestSupport() {
    }

    static void check(boolean cond, String msg) {
        System.out.println((cond ? "ok   - " : "FAIL - ") + msg);
        if (!cond) {
            failed++;
        }
    }

    static void finish(String suite) {
        if (failed > 0) {
            System.out.println(suite + ": " + failed + " check(s) failed");
            System.exit(1);
        }
        System.out.println(suite + ": all checks passed");
    }

    static Map<String, String> body(String... kv) {
        Map<String, String> m = new HashMap<>();
        for (int i = 0; i < kv.length; i += 2) {
            m.put(kv[i], kv[i + 1]);
        }
        return m;
    }

    static Response call(Application app, String method, String path, String token, Map<String, String> body) {
        Map<String, String> headers = new HashMap<>();
        if (token != null) {
            headers.put("Authorization", "Bearer " + token);
        }
        return app.handle(new Request(method, path, headers, body));
    }

    static String field(Response r, String name) {
        Matcher m = Pattern.compile("\"" + name + "\":\"([^\"]*)\"").matcher(r.body());
        return m.find() ? m.group(1) : null;
    }

    static String signUpAndLogin(Application app, String user, String password) {
        Response s = call(app, "POST", "/accounts", null, body("username", user, "email", user + "@example.com", "password", password));
        if (s.status() != 201) {
            throw new IllegalStateException("sign-up failed: " + s);
        }
        Response l = call(app, "POST", "/sessions", null, body("username", user, "password", password));
        if (l.status() != 201) {
            throw new IllegalStateException("login failed: " + l);
        }
        return field(l, "token");
    }
}

